import{z as l,x as c,o,c as A,q as E,j as n,D as a,d as r,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"执行器的实现","description":"","frontmatter":{"title":"执行器的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dbk-executor-implementation.md","filePath":"cs/dbk-executor-implementation.md","lastUpdated":1791063341000}'),B={name:"cs/dbk-executor-implementation.md"};function d(p,e,h,m,u,_){const t=c("Mermaid");return o(),A("div",null,[e[2]||(e[2]=E('<h1 id="执行器的实现" tabindex="-1">执行器的实现 <a class="header-anchor" href="#执行器的实现" aria-label="Permalink to &quot;执行器的实现&quot;">​</a></h1><div class="epigraph"><p>优化器交出的是一棵树，执行器交出去的是元组流；从树到流的那段代码，决定每个周期花在哪。</p><footer>—— 据 Graefe, *Query Evaluation Techniques*, ACM Computing Surveys, 1993；Zukowski et al., MonetDB/X100, CIDR 2005 整理</footer></div><p><a href="/cs/dbk-lsm-implementation">上一课</a>把存储引擎收成「按序吐键的归并迭代器」。同一个抽象往上长一层就是执行器：优化器在<a href="/cs/query-plan">查询计划</a>里选好的算子树，由执行器变成真的元组流。优化课已对照过 <a href="/cs/volcano-iterator">Volcano 迭代器</a>、<a href="/cs/vectorized-execution">向量化执行</a>与<a href="/cs/query-compilation">编译执行</a>的机制；本课写实现：迭代器契约长什么样、每个物理算子怎么写成状态机、内存预算与取消怎么穿过整棵树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>执行器的核心缺口只有一句话：树是静态的，流是活的。计划树在优化期定形，但每个算子在运行期是带状态的机器——排序算子要先吃完输入（阻塞算子），扫描算子吐一行算一行（流水算子）。谁保证阻塞算子不把内存吃穿？谁保证用户按了取消，一条十亿行的扫描真的会停？谁保证存储层交上来的每一行，都先过了「对我的快照可见」这道关？缺了会错在哪：内存没有预算，一个失控的哈希连接 OOM 拖死整个进程——引擎是共享服务，不是批处理作业；取消不进循环，前端早已超时，后端还在烧 CPU；可见性检查漏在扫描之外，未提交或已删除的行就流进了结果。</p><p><span class="marginnote">「阻塞算子」像接满一锅水才肯烧的壶：排序、哈希聚合必须吃完全部输入才吐得出第一行；「流水算子」像传送带：扫描、选择来一行处理一行。壶的代价是内存与首行延迟，传送带几乎不缓存——两类算子的实现与内存策略因此完全不同。</span></p><h3 id="迭代器契约" tabindex="-1">迭代器契约 <a class="header-anchor" href="#迭代器契约" aria-label="Permalink to &quot;迭代器契约&quot;">​</a></h3><p>每个算子实现三件套。<code>open</code> 分配状态：递归 open 子算子，自己领取内存上下文与参数。<code>next</code> 返回下一批元组或耗尽标记，内部按需调用子算子的 <code>next</code>。<code>close</code> 释放状态——包括向缓冲池归还所有 pin（第 1 课的契约在这里兑现）、关闭迭代器链、把内存还给上下文。三层纪律由此成立：内存是逐算子领取的预算，阻塞算子超预算就落盘外排（<a href="/cs/external-sort">外部排序</a>与 <a href="/cs/grace-hash-join">Grace hash join</a>的分相协议）；取消是一次标志检查，<code>next</code> 的批循环每轮看一眼，长扫描才可能被掐断；可见性是扫描算子的职责——每吐一行先问事务管理器（下一课）「这行对我的快照在吗」。</p><p><span class="marginnote">量级感：逐元组 <code>next()</code> 的虚调用，十亿行就是十亿次间接跳转，指令缓存反复抖动；向量化把批次定在千行量级，调用次数除以千、内层循环是紧代码——MonetDB/X100 当年量出一个数量级的差距，向量化从此成为列存引擎的地基。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算子按「要不要吃全输入」分两类实现。流水算子不缓存输入：扫描算子持一个迭代器加一个谓词（表达式树求值——行进来按 AST 走一遍，热点表达式在绑定期已做常量折叠），选择与投影几乎是免费的包装。阻塞算子有相：哈希聚合先 build 吃全输入建哈希表、组数超预算即分区落盘，再 probe 汇出结果（<a href="/cs/hash-aggregation">哈希聚合</a>）；归并连接先排两输入再归并（<a href="/cs/sort-merge-join">排序归并连接</a>）；嵌套循环给一侧建索引做探测（<a href="/cs/nlj-hash-join">嵌套循环与哈希连接</a>）。表达式求值自己也是个小执行器：AST 解释器起步，热度高了换 JIT——只是把「求值」这一层做成可替换的后端。</p><p><span class="marginnote">「外排」翻译一下就是内存装不下时分批排：先把每 10 万行在内存排成一小段写进磁盘，再把几十个有序段各拿开头做归并。数字感受：1 亿行、每段 10 万行，就是 1000 个有序段，每行大约只被读写两遍——这是阻塞算子「超预算就落盘」的底气。</span></p>',12)),(o(),n(i,null,{default:a(()=>[s(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22HashAgg%EF%BC%88open%2Fnext%2Fclose%EF%BC%89%22%5D%20--%3E%20JOIN%5B%22HashJoin%22%5D%0A%20%20JOIN%20--%3E%20BUILD%5B%22build%EF%BC%9A%E5%90%83%E5%85%A8%E8%BE%93%E5%85%A5%EF%BC%8C%E8%B6%85%E9%A2%84%E7%AE%97%E5%88%86%E5%8C%BA%E8%90%BD%E7%9B%98%22%5D%0A%20%20JOIN%20--%3E%20PROBE%5B%22probe%EF%BC%9A%E6%AF%8F%E6%89%B9%E6%B5%81%E5%BC%8F%22%5D%0A%20%20PROBE%20--%3E%20SCAN%5B%22SeqScan%EF%BC%88%E5%90%AB%E5%8F%AF%E8%A7%81%E6%80%A7%E6%A3%80%E6%9F%A5%EF%BC%89%22%5D%0A%20%20SCAN%20--%3E%20VIS%7B%22%E5%BF%AB%E7%85%A7%E5%8F%AF%E8%A7%81%EF%BC%9F%22%7D%0A%20%20VIS%20--%3E%7C%E5%90%A6%7C%20SKIP%5B%22%E8%B7%B3%E8%BF%87%E8%AF%A5%E8%A1%8C%22%5D%0A%20%20VIS%20--%3E%7C%E6%98%AF%7C%20OUT%5B%22%E4%BA%A4%E7%BB%99%E7%88%B6%E7%AE%97%E5%AD%90%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>整棵树跑起来的机制是「拉」的传递：根算子的 <code>next</code> 一路调用到叶，元组逆流而上，每层只在自己有状态的地方暂停。便宜在控制权集中——取消与内存预算顺着调用栈走；贵在逐层函数调用——向量化与编译执行都是对这一项收租方式的重构，协议本身不变。实现里最容易错的是生命周期：阻塞算子在相切换时（build 转 probe）要显式释放上一相的内存，否则预算账实不符；子算子的 <code>close</code> 必须幂等——错误路径上上层可能提前 close，已 close 的再 close 不能崩。并行执行不另起协议：把 exchange 也写成一个算子，<code>next</code> 从工作线程的队列里取批次（<a href="/cs/parallel-exchange">并行查询与 exchange</a>的语义），树形代码一行不改。</p><p>一次 next 调用如何穿过整棵树：</p>',3)),(o(),n(i,null,{default:a(()=>[s(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%88%B6%E7%AE%97%E5%AD%90%E8%B0%83%20next%20%E6%8B%89%E4%B8%80%E6%89%B9%22%5D%20--%3E%20C%5B%22%E5%AD%90%E7%AE%97%E5%AD%90%20next%20%E7%BB%A7%E7%BB%AD%E5%90%91%E4%B8%8B%E6%8B%89%22%5D%0A%20%20C%20--%3E%20L%5B%22%E5%8F%B6%E6%89%AB%E6%8F%8F%EF%BC%9A%E6%9F%A5%E5%8F%96%E6%B6%88%E6%A0%87%E5%BF%97%E4%B8%8E%E5%BF%AB%E7%85%A7%E5%8F%AF%E8%A7%81%E6%80%A7%22%5D%0A%20%20L%20--%3E%20T%5B%22%E5%90%90%E5%87%BA%E4%B8%80%E6%89%B9%E5%8F%AF%E8%A7%81%E5%85%83%E7%BB%84%22%5D%0A%20%20T%20--%3E%20U%5B%22%E5%85%83%E7%BB%84%E9%80%90%E5%B1%82%E5%90%91%E4%B8%8A%E8%BF%94%E5%9B%9E%22%5D%0A%20%20U%20--%3E%20R%5B%22%E6%A0%B9%E7%AE%97%E5%AD%90%E4%BA%A4%E7%BB%99%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=E('<p><span class="marginnote">初学者容易以为取消就是强杀线程。火山树里的取消温柔得多：只是一面旗帜，每个算子在 next 循环里看一眼、自己安静退出，内存与 pin 由 close 逐层归还。强杀线程反而会留下没归还的 pin、半写的状态，缓冲池与内存账目全乱。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课写火山家族的实现，列存与编译后端的内核机制课已对照，不展开；物化时机对扫描输出的影响（延迟物化）也不进。多查询之间的内存公平调度是资源管理问题，本课只有「逐算子预算」这一层。错误语义统一约定：任何算子的 <code>next</code> 抛错即整树 teardown，回滚范围由事务层（下一课）决定——执行器不自己回滚。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>迭代器契约三件套：open 领预算，next 查取消与可见性，close 归还 pin 与内存且幂等。</li><li>流水与阻塞算子分相实现：阻塞算子超预算即外排，不欠账。</li><li>可见性检查是扫描算子的职责，未提交的行不能流进结果。</li><li>向量化与编译是对「拉」的收租重构，不改协议；exchange 让并行不另起炉灶。</li><li>出处：Graefe, ACM Computing Surveys, 1993；Zukowski et al., CIDR 2005；Ramakrishnan and Gehrke。</li></ul>',5))])}const x=l(B,[["render",d]]);export{f as __pageData,x as default};
